const root=document.documentElement,system=matchMedia('(prefers-color-scheme: dark)');
const read=(key,fallback)=>{try{return localStorage.getItem(key)??fallback}catch{return fallback}},write=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
let theme=read('atmos-theme','system'),haptics=read('atmos-haptics','on')==='on',lastPulse=0;
export function pulse(duration=9){if(!haptics||typeof navigator.vibrate!=='function')return;const now=performance.now();if(now-lastPulse<65)return;lastPulse=now;try{navigator.vibrate(duration)}catch{}}
const palette={light:'#ffffff',dark:'#111214',yellow:'#ffdc52',red:'#b91f38',grey:'#d6dbe1'};
function applyTheme(){const selected=theme==='system'?(system.matches?'dark':'light'):(palette[theme]?theme:'light');root.dataset.theme=selected;document.querySelector('meta[name="theme-color"]').content=palette[selected];const b=document.getElementById('theme-toggle');b.textContent='◐';b.title='Theme: '+selected;b.setAttribute('aria-label','Choose a theme. Current theme: '+selected);document.querySelectorAll('[data-choice]').forEach(o=>o.setAttribute('aria-pressed',String(o.dataset.choice===selected)));document.getElementById('theme-system').setAttribute('aria-pressed',String(theme==='system'));window.dispatchEvent(new Event('atmos-theme'));}
const panel=document.getElementById('theme-panel'),toggle=document.getElementById('theme-toggle');function closeThemes(){panel.hidden=true;toggle.setAttribute('aria-expanded','false')}toggle.onclick=()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){document.getElementById('search-panel').hidden=true;panel.querySelector('[aria-pressed="true"]')?.focus()}};document.getElementById('theme-close').onclick=()=>{closeThemes();toggle.focus()};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{theme=b.dataset.choice;write('atmos-theme',theme);applyTheme()});document.getElementById('theme-system').onclick=()=>{theme='system';write('atmos-theme',theme);applyTheme()};document.addEventListener('click',e=>{if(!panel.contains(e.target)&&!toggle.contains(e.target))closeThemes()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){closeThemes();toggle.focus()}});system.addEventListener('change',()=>{if(theme==='system')applyTheme()});applyTheme();
const motionOK=!matchMedia('(prefers-reduced-motion: reduce)').matches,nav=document.querySelector('.view-nav'),indicator=nav.querySelector('.nav-indicator');function moveIndicator(){const active=nav.querySelector('[aria-current]');if(active){indicator.style.width=active.offsetWidth+'px';indicator.style.height=active.offsetHeight+'px';indicator.style.transform='translate('+active.offsetLeft+'px,'+active.offsetTop+'px)'}}new ResizeObserver(moveIndicator).observe(nav);window.addEventListener('atmos-view',()=>requestAnimationFrame(moveIndicator));requestAnimationFrame(moveIndicator);
if(motionOK){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const r=b.getBoundingClientRect(),dot=document.createElement('span');dot.className='tap-wave';dot.setAttribute('aria-hidden','true');dot.style.left=(e.clientX?r.width?e.clientX-r.left:r.width/2:r.width/2)+'px';dot.style.top=(e.clientY?e.clientY-r.top:r.height/2)+'px';b.append(dot);setTimeout(()=>dot.remove(),650)});const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');reveal.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.section-heading,.hourly,.daily').forEach(e=>{e.classList.add('reveal-on-scroll');reveal.observe(e)})}

const hapticButton=document.getElementById('haptic-toggle');function updateHaptics(){const supported=typeof navigator.vibrate==='function';hapticButton.setAttribute('aria-pressed',String(haptics&&supported));hapticButton.textContent=haptics&&supported?'Haptics on':'Haptics off';hapticButton.disabled=!supported;hapticButton.title=supported?'Toggle touch vibration':'Vibration feedback is not supported by this browser';document.getElementById('haptic-note').textContent=supported?'Light feedback for taps and timeline changes.':'This browser does not support vibration feedback.';}hapticButton.onclick=()=>{haptics=!haptics;write('atmos-haptics',haptics?'on':'off');updateHaptics();if(haptics)pulse(15)};updateHaptics();
document.addEventListener('click',e=>{const button=e.target.closest('button');if(button&&!button.disabled&&button!==hapticButton)pulse()});document.getElementById('scrubber').addEventListener('input',()=>pulse(6));
